script.code:
//Variables Externas

var TI = Ua.findNode("AGENT.OBJECTS.Simulation.Sistema_Llenado_Tanque.Caudal_Neto");
var TE = Ua.findNode("AGENT.OBJECTS.Simulation.Sistema_Llenado_Tanque.Caudal_Entrada");
var TS = Ua.findNode("AGENT.OBJECTS.Simulation.Sistema_Llenado_Tanque.Caudal_Salida");

//Variables Internas
var TN=TE.result.value-TS.result.value;


//Ejecuto Logica
if(TN==0){
	TI.result.assign({value:0});
}
else{
	TI.result.assign({value:TN});
}
